package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class PublicDecimalQuotientsTest {
 private static Question q(String prompt){return new Question(DecimalWholeQuotients.ID,prompt,"private expression","999");}
 private static Checker.Result check(Question q,String answer){return new Checker().check(q,List.of(),Collections.singletonList(answer));}
 @Test public void GeneralOriginalsGiveExactQuotientsWithoutSelectedBoundsOrStoredKeys(){
  for(String[] row:new String[][]{{"123.4567 ÷ 12","1234567/120000"},{"1.0001 / 100","0.010001"},{"0.000 ÷ 99","0"},{"00001.000 ÷ 000003","1/3"},{"1 ÷ 3","1/3"},{"100.00 ÷ 12","25/3"},{"999999999.999999999999 ÷ 999999937","999999999999999999999/999999937000000000000"}}){Question q=q(row[0]);var original=DecimalWholeQuotients.readGeneral(q);assertNotNull(original);assertEquals(DecimalWholeQuotients.numericInput(row[1]),original.value());assertTrue(check(q,row[1]).correct());assertFalse(check(q,"999").correct());q.expression=null;q.answers=null;assertTrue(check(q,row[1]).correct());assertTrue(CurriculumLimits.NONE.allows(q));assertEquals(row[0],q.prompt);}
  var raw=DecimalWholeQuotients.readGeneral(q("00012.3400 ÷ 000002"));assertEquals("00012.3400",raw.raw());assertEquals("000002",raw.divisorRaw());assertEquals(new BigInteger("2"),raw.divisor());assertTrue(raw.finitePossible());assertNull(DecimalWholeQuotients.read(q("123.4567 ÷ 12")));assertNotNull(DecimalWholeQuotients.readGeneral(q("123.4567 ÷ 12")));
 }
 @Test public void ReadOnlySevenAndNineGuidesKeepLegacyMetadataAndDraftResultFrames(){
  Question finite=q("99.9 ÷ 16");finite.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=finite.studyGuide;Question legacy=q("99.9 ÷ 16");DecimalArithmeticRelations.attach(legacy);StudyGuide guide=DecimalWholeQuotients.guide(finite);assertEquals("decimal-arithmetic-relations-v1",guide.teachingVersion);assertEquals(7,guide.frames.size());for(int i=0;i<7;i++){var expected=legacy.studyGuide.frames.get(i);var actual=guide.frames.get(i);assertEquals(expected.instruction,actual.instruction);assertEquals(expected.before,actual.before);assertEquals(expected.after,actual.after);assertEquals(expected.expected,actual.expected);assertEquals(expected.inputFormat,actual.inputFormat);}assertEquals(7,HelpPlan.forQuestion(finite).size());assertSame(stored,finite.studyGuide);
  Question fraction=q("1.0 ÷ 3");fraction.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide privateGuide=fraction.studyGuide;guide=DecimalWholeQuotients.guide(fraction);assertEquals("decimal-whole-quotient-v1",guide.teachingVersion);assertEquals(Integer.valueOf(7),guide.resultNumeratorFrame);assertEquals(Integer.valueOf(8),guide.resultDenominatorFrame);List<String> expected=List.of("1.0","3","1","10","10","30","10","1","3");assertEquals(expected,guide.frames.stream().map(f->f.expected).toList());assertEquals(List.of("나누어지는 수를 쓰세요.","나누는 수를 쓰세요.","왼쪽 수의 소수점 아래 자릿수를 쓰세요.","옮길 자릿수에 맞는 자릿값 배수를 쓰세요.","소수점을 옮겨 나누어지는 수를 정수로 쓰세요.","자릿값 배수에 나누는 수를 곱해 분모를 구하세요.","분자와 분모의 최대공약수를 구하세요.","옮긴 수를 최대공약수로 나누어 분자를 구하세요.","분모를 같은 최대공약수로 나누세요."),guide.frames.stream().map(f->f.instruction).toList());assertEquals("decimalValue",guide.frames.get(0).inputFormat);for(int i=1;i<9;i++)assertTrue(guide.frames.get(i).inputFormat==null||guide.frames.get(i).inputFormat.isEmpty());HelpPlan h=HelpPlan.forQuestion(fraction);assertFalse(h.canTransfer());assertSame(privateGuide,fraction.studyGuide);assertEquals("private expression",fraction.expression);assertArrayEquals(new String[]{"999"},fraction.answers);HelpPlan.Draft draft=h.restore(null,fraction.id);draft.entries=new ArrayList<>(expected);draft.entries.set(7,"0000000000000000000000000000000000000001");draft.stage=9;assertEquals(9,h.restore(draft.copy(),fraction.id).stage);assertEquals("1/3",h.enteredAnswer(draft));assertEquals("decimal-whole-quotient-v1",draft.teachingVersion);
 }
 @Test public void LongFiniteDecimalsAndBigIntegerFractionStagesRemainReachable(){
  Question finite=q("0.000000000001 ÷ 536870912");String answer="0.00000000000000000000186264514923095703125";assertTrue(DecimalWholeQuotients.readGeneral(finite).finitePossible());assertTrue(check(finite,answer).correct());HelpPlan h=HelpPlan.forQuestion(finite);List<String> entered=List.of("0.000000000001","536870912","12","1000000000000","1","0.00000000186264514923095703125",answer);assertEquals(7,h.size());for(int i=0;i<entered.size();i++)assertTrue("finite"+i,h.step(i).accepts(entered.get(i)));assertFalse(h.step(6).accepts(answer+"1"));try{Expression.number(answer);fail("Shared12-place guard widened");}catch(IllegalArgumentException expected){}
  Question fraction=q("999999999.999999999999 ÷ 999999937");h=HelpPlan.forQuestion(fraction);entered=List.of("999999999.999999999999","999999937","12","1000000000000","999999999999999999999","999999937000000000000","1","999999999999999999999","999999937000000000000");assertEquals(9,h.size());for(int i=0;i<entered.size();i++)assertTrue("fraction"+i,h.step(i).accepts(entered.get(i)));assertTrue(h.step(2).accepts("12/1"));assertFalse(h.step(0).accepts("999999999999999999999/1000000000000"));HelpPlan.Draft draft=h.restore(null,fraction.id);draft.entries=new ArrayList<>(entered);draft.stage=9;assertEquals("999999999999999999999/999999937000000000000",h.enteredAnswer(draft));assertTrue(check(fraction,h.enteredAnswer(draft)).correct());assertFalse(h.canTransfer());
 }
 @Test public void ReferencesAreRelevantCheckedLearnerValuesWithCompleteOriginalLabels(){
  Question finite=q("99.9 ÷ 16");List<String> entered=List.of("99.90","016","1","10","0999.0","62.4375");assertEquals(Map.of("옮긴 왼쪽 수 A = x × u = ","0999.0","오른쪽 수 y = ","016"),DecimalWholeQuotients.references(finite,5,entered));assertEquals(Map.of("먼저 구한 몫 r = A ÷ y = ","62.4375","자릿값 배수 u = p칸 이동에 맞는 배수 = ","10"),DecimalWholeQuotients.references(finite,6,entered));assertEquals(Map.of("오른쪽 수 y = ","016"),DecimalWholeQuotients.references(finite,5,List.of("99.9","016","1","10","999.1")));
  Question fraction=q("1.0 ÷ 3");entered=List.of("1.00","3","1","10","10","30","10","1");assertEquals(Map.of("옮긴 수 A = x × u = ","10","분모 D = u × d = ","30"),DecimalWholeQuotients.references(fraction,6,entered));assertEquals(Map.of("분모 D = u × d = ","30","최대공약수 g = gcd(A, D) = ","10"),DecimalWholeQuotients.references(fraction,8,entered));assertTrue(DecimalWholeQuotients.references(fraction,8,List.of("1.0","3","1","10","10","31","9","1")).isEmpty());assertTrue(DecimalWholeQuotients.references(fraction,0,entered).isEmpty());assertTrue(DecimalWholeQuotients.references(fraction,9,entered).isEmpty());assertTrue(DecimalWholeQuotients.references(null,0,entered).isEmpty());assertTrue(DecimalWholeQuotients.references(finite,5,null).isEmpty());
 }
 @Test public void OptionalFullAndPartialWorkUsePublicQuotientAndRetainWorkTargets(){
  Question q=q("1.0 ÷ 3");q.kind="complexRoots";q.calculationMethod="written";Checker checker=new Checker();assertTrue(checker.check(q,List.of("1.0/3=1/3"),List.of("1/3"),List.of(Checker.StepKind.FULL)).correct());assertTrue(checker.checkSteps(q,List.of("1.0/3=1/3"),List.of(Checker.StepKind.FULL)).correct());Checker.Result wrong=checker.check(q,List.of("999=999"),List.of("1/3"),List.of(Checker.StepKind.FULL));assertEquals(Checker.Status.WRONG_STEP,wrong.status);assertEquals(Checker.InputTarget.WORK,wrong.inputTarget);assertEquals(0,wrong.index);Checker.Result incomplete=checker.check(q,List.of("1.0/3="),List.of("1/3"),List.of(Checker.StepKind.FULL));assertEquals(Checker.Status.INPUT_NEEDED,incomplete.status);assertEquals(Checker.InputTarget.WORK,incomplete.inputTarget);assertTrue(checker.check(q,List.of("6/3=2"),List.of("1/3"),List.of(Checker.StepKind.PARTIAL)).correct());assertEquals("complexRoots",q.kind);assertEquals("private expression",q.expression);assertArrayEquals(new String[]{"999"},q.answers);q.stepSupport=false;assertEquals(Checker.Status.INPUT_NEEDED,checker.check(q,List.of("1.0/3=1/3"),List.of("1/3"),List.of(Checker.StepKind.FULL)).status);assertTrue(checker.check(q,List.of("6/3=2"),List.of("1/3"),List.of(Checker.StepKind.PARTIAL)).correct());
 }
 @Test public void ExplicitFormatsSourceGuardsAndMalformedInputsCannotUsePrivateFallback(){
  assertFalse(DecimalWholeQuotients.acceptsStep("1÷2","0.5","decimalValue"));assertFalse(DecimalWholeQuotients.acceptsStep("1.0÷2","0.5","decimal"));assertTrue(DecimalWholeQuotients.acceptsStep("0.50","0.5","decimalValue"));
  Question finite=q("1.0 ÷ 2");finite.answerFormat="decimalValue";assertTrue(check(finite,"0.5000").correct());assertTrue(check(finite," 0 . 5 ").correct());assertEquals(Checker.Status.INPUT_NEEDED,check(finite,"1/2").status);finite.answerFormat="decimal";assertTrue(check(finite,"0.5").correct());assertEquals(Checker.Status.INPUT_NEEDED,check(finite,"1/2").status);finite.answerFormat="fraction";assertTrue(check(finite,"2/4").correct());assertEquals(Checker.Status.INPUT_NEEDED,check(finite,"0.5").status);Question nonterm=q("1.0 ÷ 3");assertEquals(Checker.Status.WRONG_ANSWER,check(nonterm,"0.333").status);nonterm.answerFormat="fraction";assertTrue(check(nonterm,"2/6").correct());assertEquals(Checker.Status.INPUT_NEEDED,check(nonterm,"0.333").status);Question whole=q("2.0 ÷ 2");whole.answerFormat="decimal";assertEquals(Checker.Status.INPUT_NEEDED,check(whole,"1").status);assertTrue(check(whole,"1.0").correct());
  for(String prompt:List.of("1.0 ÷ 0","1.0 ÷ 000000000","1.0 ÷ -2","-1.0 ÷ 2","1000000000 ÷ 2","1.2345678901234 ÷ 2","1.0 ÷ 1000000000","1.0 ÷ 2.0","1.0 ÷ .2","1e2 ÷ 2","1.0 × 2","1.0 ÷ 2 ÷ 3","1. ÷ 2","1/2 ÷ 2")){Question q=q(prompt);q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;assertNull(DecimalWholeQuotients.readGeneral(q));assertNull(DecimalWholeQuotients.guide(q));assertNull(HelpPlan.forQuestion(q));assertNull(DecimalWholeQuotients.workQuestion(q));assertNull(DecimalWholeQuotients.value(q));assertSame(stored,q.studyGuide);assertEquals(Checker.Status.INPUT_NEEDED,check(q,"999").status);assertFalse(CurriculumLimits.NONE.allows(q));}for(String invalid:List.of("1/0","1e0","1+0","1,0","1.","1".repeat(121),"1".repeat(241))){assertNull(DecimalWholeQuotients.numericInput(invalid));assertEquals(Checker.Status.INPUT_NEEDED,check(nonterm,invalid).status);}assertEquals(Checker.Status.INPUT_NEEDED,check(nonterm,null).status);assertNull(DecimalWholeQuotients.numericInput(null));assertNull(DecimalWholeQuotients.readGeneral(null));assertNull(DecimalWholeQuotients.readGeneral(new Question("decimalDiv","1 ÷ 2","","0.5")));
 }
}
